self.onmessage=function(e){if("start"===e.data.action)self.timerInterval&&clearInterval(self.timerInterval),self.endTime=Date.now()+1e3*e.data.duration,self.timerInterval=setInterval(()=>{const now=Date.now(),remaining=Math.ceil((self.endTime-now)/1e3);remaining<=0?(clearInterval(self.timerInterval),self.postMessage({action:"complete"})):self.postMessage({action:"tick",remaining})},250);else if("stop"===e.data.action)self.timerInterval&&(clearInterval(self.timerInterval),self.timerInterval=null);else if("adjust"===e.data.action&&self.timerInterval&&self.endTime){self.endTime+=1e3*e.data.seconds;const now=Date.now(),remaining=Math.max(0,Math.ceil((self.endTime-now)/1e3));self.postMessage({action:"tick",remaining})}};